/// Preset site catalogue (`assets/data/sites.json`) and horizon masks
/// (`assets/data/horizons.json`), both generated by the pipeline.
library;

import 'dart:convert';
import 'dart:typed_data';

import 'horizon.dart';

class SiteSource {
  final String title, url, says;
  const SiteSource(this.title, this.url, this.says);
}

class SiteGroup {
  final String id, name, note;
  const SiteGroup(this.id, this.name, this.note);
}

class Site {
  final String id, name, short, group, kind, confidence, notes;
  final double lat, lon;

  /// Terrain height above the 1737.4 km sphere at the site (LOLA), metres.
  final double terrainHeightM;
  final double slopeDeg, horizonMaxDeg, horizonMaxAzDeg, horizonMaxDistanceKm;
  final double longTermSunlitPct, longTermEarthPct, longTermBothPct;
  final List<SiteSource> sources;

  /// True for user-placed sites (horizon from the coarse on-device DEM).
  final bool custom;

  const Site({
    required this.id,
    required this.name,
    required this.short,
    required this.group,
    required this.kind,
    required this.confidence,
    required this.notes,
    required this.lat,
    required this.lon,
    required this.terrainHeightM,
    this.slopeDeg = double.nan,
    this.horizonMaxDeg = double.nan,
    this.horizonMaxAzDeg = double.nan,
    this.horizonMaxDistanceKm = double.nan,
    this.longTermSunlitPct = double.nan,
    this.longTermEarthPct = double.nan,
    this.longTermBothPct = double.nan,
    this.sources = const [],
    this.custom = false,
  });

  factory Site.fromJson(Map<String, dynamic> j) {
    double d(String k) => (j[k] as num?)?.toDouble() ?? double.nan;
    return Site(
      id: j['id'] as String,
      name: j['name'] as String,
      short: (j['short'] ?? j['name']) as String,
      group: (j['group'] ?? '') as String,
      kind: (j['kind'] ?? '') as String,
      confidence: (j['confidence'] ?? '') as String,
      notes: (j['notes'] ?? '') as String,
      lat: d('lat'),
      lon: d('lon'),
      terrainHeightM: d('terrainHeightM'),
      slopeDeg: d('slopeDeg'),
      horizonMaxDeg: d('horizonMaxDeg'),
      horizonMaxAzDeg: d('horizonMaxAzDeg'),
      horizonMaxDistanceKm: d('horizonMaxDistanceKm'),
      longTermSunlitPct: d('longTermSunlitPct'),
      longTermEarthPct: d('longTermEarthPct'),
      longTermBothPct: d('longTermBothPct'),
      sources: [
        for (final s in (j['sources'] as List? ?? const []))
          SiteSource((s['title'] ?? '') as String, (s['url'] ?? '') as String, (s['says'] ?? '') as String)
      ],
    );
  }

  /// "Approximate region centre" etc. for UI labels.
  bool get isRegionCentre => kind == 'region-center-approx';
}

class SiteCatalog {
  final List<SiteGroup> groups;
  final List<Site> sites;

  /// masks[siteId][observerHeightM]
  final Map<String, Map<double, HorizonMask>> masks;
  final List<double> heightsM;
  final String demDescription;

  SiteCatalog(this.groups, this.sites, this.masks, this.heightsM, this.demDescription);

  factory SiteCatalog.parse(String sitesJson, String horizonsJson) {
    final s = jsonDecode(sitesJson) as Map<String, dynamic>;
    final h = jsonDecode(horizonsJson) as Map<String, dynamic>;
    final step = (h['azStepDeg'] as num).toDouble();
    final heights = [for (final x in h['heightsM'] as List) (x as num).toDouble()];
    final dem = (s['dem'] ?? '') as String;
    final masks = <String, Map<double, HorizonMask>>{};
    (h['masks'] as Map<String, dynamic>).forEach((id, byHeight) {
      final m = <double, HorizonMask>{};
      (byHeight as Map<String, dynamic>).forEach((hk, centi) {
        final hm = double.parse(hk);
        m[hm] = HorizonMask.fromCentideg(step, centi as List, source: 'LOLA 80 m + 240 m DEM, ${hk}m observer');
      });
      masks[id] = m;
    });
    return SiteCatalog(
      [for (final g in (s['groups'] as List? ?? const [])) SiteGroup(g['id'] as String, g['name'] as String, (g['note'] ?? '') as String)],
      [for (final x in s['sites'] as List) Site.fromJson(x as Map<String, dynamic>)],
      masks,
      heights,
      dem,
    );
  }

  Site byId(String id) => sites.firstWhere((s) => s.id == id);

  HorizonMask? mask(String siteId, double observerHeightM) => masks[siteId]?[observerHeightM];
}

/// Convenience for tests and tools: a flat mask (smooth-sphere horizon at [dipDeg]).
HorizonMask flatMask(double dipDeg, {double stepDeg = 0.25}) =>
    HorizonMask(stepDeg, Float64List(360 ~/ stepDeg)..fillRange(0, 360 ~/ stepDeg, dipDeg),
        source: 'flat', approximate: true);
